import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";

type Turn={date:string;turn_id:string;status:string;latest_modified:string;request_file:string|null;response_file:string|null};
type Group={date:string;turns:Turn[]};
type Call={teammate?:string;name?:string;parameters:unknown;plan_index:number;action_index:number};
type Detail=Turn&{request_text:string|null;response_text:string|null;parsed_response:unknown;parse_error:string|null;function_calls:Call[]};
const key=(t:Turn)=>`${t.date}/${t.turn_id}`;
const time=(v:string)=>v?new Date(v).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit",second:"2-digit"}):"";

export default function App(){
 const [groups,setGroups]=useState<Group[]>([]),[selected,setSelected]=useState(""),[detail,setDetail]=useState<Detail|null>(null),[polling,setPolling]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(""),[refreshed,setRefreshed]=useState<Date>();
 const all=useMemo(()=>groups.flatMap(g=>g.turns),[groups]);
 const open=useCallback(async(t:Turn)=>{setSelected(key(t));setDetail(null);const r=await fetch(`/api/turns/${encodeURIComponent(t.date)}/${encodeURIComponent(t.turn_id)}`);if(!r.ok)throw Error("Unable to load this turn");setDetail(await r.json());},[]);
 const refresh=useCallback(async()=>{setBusy(true);setError("");try{const r=await fetch("/api/turns");if(!r.ok)throw Error("Unable to scan the log directory");const data=await r.json() as {dates:Group[]};setGroups(data.dates);setRefreshed(new Date());const flat=data.dates.flatMap(g=>g.turns);const next=flat.find(t=>key(t)===selected)||flat.find(t=>t.status==="complete");if(next&&(!detail||key(next)!==selected))await open(next);}catch(e){setError(e instanceof Error?e.message:"Refresh failed");}finally{setBusy(false);}},[detail,open,selected]);
 useEffect(()=>{void refresh();},[]);useEffect(()=>{if(!polling)return;const id=window.setInterval(()=>void refresh(),5000);return()=>window.clearInterval(id);},[polling,refresh]);
 useEffect(()=>{const title=document.querySelector(".detail-title") as HTMLElement|null;const status=title?.querySelector("i") as HTMLElement|null;if(title)title.style.justifyContent="flex-start";if(status)status.style.marginLeft="auto";},[detail]);
 const openLocation=async()=>{if(!detail)return;const r=await fetch(`/api/turns/${encodeURIComponent(detail.date)}/${encodeURIComponent(detail.turn_id)}/open-location`);if(!r.ok)setError("Unable to open file location");};
 return <main><header><div><small>MINDSAND LOG VIEWER</small><h1>MindSand</h1></div><div className="actions"><label><input type="checkbox" checked={polling} onChange={e=>setPolling(e.target.checked)}/> Poll every 5s</label><button onClick={()=>void refresh()} disabled={busy}>{busy?"Refreshing…":"Refresh"}</button></div></header>{error&&<div className="error">{error}</div>}<div className="layout"><aside><div className="side-title"><b> </b><span>{all.length}</span></div>{groups.map(g=><section key={g.date}><h2>{g.date}</h2>{g.turns.map(t=><button className={`turn ${selected===key(t)?"active":""}`} key={key(t)} onClick={()=>void open(t)}><span><strong>{t.turn_id}</strong><em>{time(t.latest_modified)}</em></span><i className={t.status==="complete"?"complete":"partial"}>{t.status==="complete"?"paired":t.status}</i></button>)}</section>)}{!all.length&&!error&&<p className="muted">No matching files.</p>}</aside><article>{detail?<><div className="detail-title"><div><small>{detail.date} · {detail.turn_id}</small><h2>Request / response</h2></div><button onClick={()=>void openLocation()} aria-label="Open file location" title="Open file location" style={{width:30,height:30,padding:6,border:"1px solid #38546a",borderRadius:4,background:"#1d3040",color:"#b9ead7",display:"flex",alignItems:"center",justifyContent:"center",order:-1,marginRight:8}}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true"><path d="M3 6.5A2.5 2.5 0 0 1 5.5 4H10l2 2h6.5A2.5 2.5 0 0 1 21 8.5v9a2.5 2.5 0 0 1-2.5 2.5h-13A2.5 2.5 0 0 1 3 17.5z"/></svg></button><i className={detail.status==="complete"?"complete":"partial"}>{detail.status}</i></div><div className="panes"><Panel title="Request" file={detail.request_file}><pre>{detail.request_text||"No request file found."}</pre></Panel><Panel title="Function calls" file={`${detail.function_calls.length} calls`}><div>{detail.function_calls.map(c=><div className="call" key={`${c.plan_index}-${c.action_index}`}><b>{c.name||"Unnamed action"}</b><span>{c.teammate||"Unknown teammate"}</span><pre>{JSON.stringify(c.parameters,null,2)}</pre></div>)}</div>{!detail.function_calls.length&&<p className="muted">No Plans[].actions[] calls found.</p>}</Panel><Panel title="Response JSON" file={detail.response_file}><pre>{detail.parse_error?`${detail.parse_error}\n\n${detail.response_text||""}`:JSON.stringify(detail.parsed_response,null,2)||"No response file found."}</pre></Panel></div></>:<div className="welcome"><h2>Select a turn</h2><p>Choose a pair to inspect its request and planned actions.</p></div>}{refreshed&&<footer>Last refreshed {refreshed.toLocaleTimeString()}</footer>}</article></div></main>;
}
function Panel({title,file,children}:{title:string;file:string|null;children:ReactNode}){const [copied,setCopied]=useState(false);const copy=async(e:React.MouseEvent<HTMLButtonElement>)=>{const text=e.currentTarget.closest(".panel")?.querySelector("pre")?.textContent||"";await navigator.clipboard.writeText(text);setCopied(true);window.setTimeout(()=>setCopied(false),1500);};return <section className="panel"><div className="panel-head"><b>{title}</b><div style={{display:"flex",alignItems:"center",gap:10,minWidth:0}}>{title==="Response JSON"&&<button aria-label="Copy JSON response" title="Copy JSON response" onClick={copy} style={{border:"1px solid #38546a",borderRadius:4,background:"#1d3040",color:"#b9ead7",padding:"4px 8px",fontSize:16,lineHeight:1}}>{copied?"✓":"⧉"}</button>}<span>{file||"Missing"}</span></div></div>{children}</section>}

